package art

import (
	"bytes"
	"fmt"
	"image"

	_ "image/png" // register the PNG decoder for the shared guard

	_ "golang.org/x/image/webp" // register the WebP decoder (decode-only: crops are always JPEG)
)

// guard gates fetched and uploaded bytes identically — the ONE image guard:
// the ≤8 MiB cap (ErrTooLarge), the JPEG/PNG/WebP magic sniff (ErrNotImage),
// then a REAL decode proving the bytes render. Returns the sniffed ext the
// blob file is stored under.
func guard(body []byte) (string, error) {
	if len(body) > maxArtBytes {
		return "", fmt.Errorf("%w: got %d bytes", ErrTooLarge, len(body))
	}
	ext := sniffImage(body)
	if ext == "" {
		return "", fmt.Errorf("%w: %d bytes, unknown magic", ErrNotImage, len(body))
	}
	if _, format, err := image.Decode(bytes.NewReader(body)); err != nil {
		return "", fmt.Errorf("%w: %s decode: %v", ErrNotImage, ext, err)
	} else if format != ext {
		// The decode-dispatched format must agree with the magic sniff.
		return "", fmt.Errorf("%w: magic says %s, decoded as %s", ErrNotImage, ext, format)
	}
	return ext, nil
}

// sniffImage reports the stored ext for an image magic prefix — jpeg, png,
// or webp — or "" when the bytes front-run no known format.
func sniffImage(b []byte) string {
	switch {
	case len(b) >= 3 && b[0] == 0xFF && b[1] == 0xD8 && b[2] == 0xFF:
		return "jpeg"
	case len(b) >= 8 && bytes.Equal(b[:8], []byte{0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A}):
		return "png"
	case len(b) >= 12 && bytes.Equal(b[:4], []byte("RIFF")) && bytes.Equal(b[8:12], []byte("WEBP")):
		return "webp"
	default:
		return ""
	}
}
